class LRUCache
  def initialize(capacity)
    @capacity = capacity
    @cache = {}
  end

  def get(key)
    return nil unless @cache.key?(key)

    value = @cache.delete(key)
    @cache[key] = value
  end

  def put(key, value)
    @cache.delete(key)
    @cache[key] = value
    @cache.shift if @cache.length > @capacity
  end
end
